const DB_NAME = 'dickalicious-videos';
const DB_VERSION = 1;
const STORE_NAME = 'blobs';

/** Warn users above this size; IndexedDB still used for all uploads. */
export const MAX_VIDEO_BYTES = 50 * 1024 * 1024;

export function formatVideoSizeError(fileSize: number): string {
  return `Video too large (${formatMb(fileSize)}). Maximum ${formatMb(MAX_VIDEO_BYTES)} per file.`;
}

export function formatMb(bytes: number): string {
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onerror = () => reject(req.error ?? new Error('IndexedDB open failed'));
    req.onsuccess = () => resolve(req.result);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
  });
}

export async function putVideoBlob(id: string, blob: Blob): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(blob, id);
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => {
      db.close();
      reject(tx.error ?? new Error('Failed to store video'));
    };
  });
}

export async function getVideoBlob(id: string): Promise<Blob | null> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const req = tx.objectStore(STORE_NAME).get(id);
    req.onsuccess = () => {
      db.close();
      resolve((req.result as Blob | undefined) ?? null);
    };
    req.onerror = () => {
      db.close();
      reject(req.error ?? new Error('Failed to read video'));
    };
  });
}

export async function deleteVideoBlob(id: string): Promise<void> {
  const db = await openDb();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).delete(id);
    tx.oncomplete = () => {
      db.close();
      resolve();
    };
    tx.onerror = () => {
      db.close();
      reject(tx.error ?? new Error('Failed to delete video'));
    };
  });
}

export async function deleteVideoBlobs(ids: string[]): Promise<void> {
  await Promise.all(ids.map((id) => deleteVideoBlob(id)));
}

import { useEffect, useState } from 'react';
import { getVideoBlob } from '../lib/videoStorage';

export function useVideoBlobUrl(videoId: string | undefined): {
  url: string | null;
  loading: boolean;
  error: string | null;
} {
  const [url, setUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(!!videoId);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!videoId) {
      setUrl(null);
      setLoading(false);
      setError(null);
      return;
    }

    let revoked = false;
    let objectUrl: string | null = null;
    setLoading(true);
    setError(null);
    setUrl(null);

    void getVideoBlob(videoId)
      .then((blob) => {
        if (revoked) return;
        if (!blob) {
          setError('Video file not found.');
          setUrl(null);
          return;
        }
        objectUrl = URL.createObjectURL(blob);
        setUrl(objectUrl);
      })
      .catch(() => {
        if (!revoked) setError('Could not load video.');
      })
      .finally(() => {
        if (!revoked) setLoading(false);
      });

    return () => {
      revoked = true;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [videoId]);

  return { url, loading, error };
}

