import { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { VideoCategoryCard } from '../components/VideoCategoryCard';
import { useAppStore } from '../hooks/useAppStore';

export function Videos() {
  const { state, session } = useAppStore();
  const [search, setSearch] = useState('');
  const isAdmin = session?.role === 'admin';

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return state.videoCategories;
    return state.videoCategories.filter(
      (c) =>
        c.name.toLowerCase().includes(q) ||
        (c.description ?? '').toLowerCase().includes(q),
    );
  }, [state.videoCategories, search]);

  const videoCountByCategory = (categoryId: string) =>
    state.videos.filter((v) => v.categoryId === categoryId).length;

  return (
    <div className="page">
      <header className="page-header">
        <h2>Videos</h2>
        <p className="muted">Browse videos by category</p>
      </header>

      {state.videoCategories.length > 0 && (
        <div className="filters">
          <input
            type="search"
            placeholder="Search categories…"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            aria-label="Search video categories"
          />
        </div>
      )}

      {state.videoCategories.length === 0 ? (
        <section className="card">
          <p className="muted">
            No video categories yet.
            {isAdmin ? (
              <>
                {' '}
                <Link to="/admin">Create categories in Admin</Link> under Videos.
              </>
            ) : (
              ' An admin can add video categories and uploads.'
            )}
          </p>
        </section>
      ) : filtered.length === 0 ? (
        <section className="card">
          <p className="muted">No categories match your search.</p>
        </section>
      ) : (
        <section>
          <h2 className="section-title">Categories</h2>
          <div className="category-grid">
            {filtered.map((cat) => (
              <VideoCategoryCard
                key={cat.id}
                category={cat}
                videoCount={videoCountByCategory(cat.id)}
              />
            ))}
          </div>
        </section>
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { useAppStore } from '../hooks/useAppStore';
import { useVideoBlobUrl } from '../hooks/useVideoBlobUrl';
import type { Video } from '../types';

function VideoPlayer({ video }: { video: Video }) {
  const { url, loading, error } = useVideoBlobUrl(video.id);

  if (loading) {
    return <p className="muted">Loading video…</p>;
  }
  if (error || !url) {
    return <p className="login-error">{error ?? 'Video unavailable.'}</p>;
  }

  return (
    <video
      className="video-player"
      controls
      src={url}
      preload="metadata"
      aria-label={video.title}
    />
  );
}

function VideoListItem({
  video,
  selected,
  onSelect,
}: {
  video: Video;
  selected: boolean;
  onSelect: () => void;
}) {
  return (
    <button
      type="button"
      className={
        selected ? 'video-list-item video-list-item--active' : 'video-list-item'
      }
      onClick={onSelect}
    >
      <span className="video-list-item__icon" aria-hidden>
        🎬
      </span>
      <span className="video-list-item__body">
        <strong>{video.title}</strong>
        {video.description && (
          <span className="muted video-list-item__desc">{video.description}</span>
        )}
      </span>
    </button>
  );
}

export function VideoCategoryDetail() {
  const { categoryId } = useParams<{ categoryId: string }>();
  const { state } = useAppStore();
  const [playingId, setPlayingId] = useState<string | null>(null);

  const category = state.videoCategories.find((c) => c.id === categoryId);
  const videos = useMemo(
    () =>
      state.videos
        .filter((v) => v.categoryId === categoryId)
        .sort(
          (a, b) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
        ),
    [state.videos, categoryId],
  );

  const playing = videos.find((v) => v.id === playingId) ?? videos[0] ?? null;

  if (!category) {
    return (
      <div className="page">
        <header className="page-header">
          <h2>Category not found</h2>
          <p className="muted">
            <Link to="/videos">Back to Videos</Link>
          </p>
        </header>
      </div>
    );
  }

  return (
    <div className="page">
      <header className="page-header">
        <p className="muted">
          <Link to="/videos">← Videos</Link>
        </p>
        <h2>
          {category.icon ?? '🎬'} {category.name}
        </h2>
        {category.description && (
          <p className="muted">{category.description}</p>
        )}
      </header>

      {videos.length === 0 ? (
        <section className="card">
          <p className="muted">No videos in this category yet.</p>
        </section>
      ) : (
        <>
          {playing && (
            <section className="card video-watch-card">
              <h3 className="section-title">{playing.title}</h3>
              <VideoPlayer video={playing} />
              {playing.description && (
                <p className="muted video-watch-card__desc">{playing.description}</p>
              )}
            </section>
          )}

          <section>
            <h3 className="section-title">All videos</h3>
            <div className="video-list">
              {videos.map((v) => (
                <VideoListItem
                  key={v.id}
                  video={v}
                  selected={playing?.id === v.id}
                  onSelect={() => setPlayingId(v.id)}
                />
              ))}
            </div>
          </section>
        </>
      )}
    </div>
  );
}

