    return { ok: false, error: formatVideoSizeError(file.size) };
  }
  try {
    await putVideoBlob(video.id, file);
  } catch {
    return { ok: false, error: 'Could not store video (storage full?).' };
  }
  persist({ ...state, videos: [...state.videos, video] });
  return { ok: true };
},
deleteVideo: (id) => {
  void deleteVideoBlob(id);
  persist({
    ...state,
    videos: state.videos.filter((v) => v.id !== id),
  });
},
