    <section className="card">
      <h3 className="section-title">Upload video</h3>
      <StatusMessage message={error} variant="err" />
      <StatusMessage message={message} />

      <FormBlock title="Details">
        <Field label="Title" htmlFor="vid-title" required>
          <input
            id="vid-title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
        </Field>
        <Field label="Category" htmlFor="vid-cat" required>
          <select
            id="vid-cat"
            value={categoryId}
            onChange={(e) => setCategoryId(e.target.value)}
          >
            <option value="">Select category…</option>
            {state.videoCategories.map((c) => (
              <option key={c.id} value={c.id}>
                {c.icon ?? '🎬'} {c.name}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Description" htmlFor="vid-desc">
          <textarea
            id="vid-desc"
            rows={2}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
        </Field>
        <Field
          label="Video file"
          htmlFor="vid-file"
          hint={`accept video/* · max ${formatMb(MAX_VIDEO_BYTES)}`}
          required
        >
          <input
            id="vid-file"
            type="file"
            accept="video/*"
            onChange={(e) => setFile(e.target.files?.[0] ?? null)}
          />
          {file && (
            <p className="muted">
              {file.name} ({formatMb(file.size)})
            </p>
          )}
        </Field>
      </FormBlock>

      <FormActions
        editing={false}
        entityLabel="video"
        onSubmit={() => void submit()}
        onClear={() => {
          setTitle('');
          setDescription('');
          setCategoryId('');
          setFile(null);
          setError('');
          setMessage('');
        }}
        disabled={uploading}
      />
    </section>
  );

  return <AdminSection list={list} form={form} />;
}

